import { useRef } from 'react';
import './tokenized-search.css';

export type SearchToken = { id: string; label: string };
type Props = { tokens: readonly SearchToken[]; text: string; onTextChange: (text: string) => void; onTokensChange: (tokens: SearchToken[]) => void; onRequestSuggestions: (text: string) => void; onSubmit: () => void; onReplaceToken: (token: SearchToken) => void };

export function TokenizedSearch({ tokens, text, onTextChange, onTokensChange, onRequestSuggestions, onSubmit, onReplaceToken }: Props) {
  const input = useRef<HTMLInputElement>(null);
  function focusInput() { input.current?.focus(); }
  function removeAt(index: number) { onTokensChange(tokens.filter((_, itemIndex) => itemIndex !== index)); requestAnimationFrame(focusInput); }
  return <form className="tokenSearch" role="search" onSubmit={event => { event.preventDefault(); onSubmit(); }} onClick={focusInput}>
    <span className="searchIcon" aria-hidden="true">⌕</span>
    <div className="searchContents">{tokens.map((token, index) => <span className="searchToken" key={token.id}><button type="button" className="tokenLabel" aria-label={`Edit filter ${token.label}`} onClick={event => { event.stopPropagation(); onReplaceToken(token); }}>{token.label}</button><button type="button" className="tokenRemove" aria-label={`Remove filter ${token.label}`} onClick={event => { event.stopPropagation(); removeAt(index); }}>×</button></span>)}
      <input ref={input} type="search" role="searchbox" aria-label="Search and filters" value={text} autoComplete="off" onChange={event => { onTextChange(event.target.value); onRequestSuggestions(event.target.value); }} onKeyDown={event => { if (event.key === 'Backspace' && !text && tokens.length) { event.preventDefault(); removeAt(tokens.length - 1); } }} /></div>
    {(text || tokens.length > 0) && <button type="button" className="clearSearch" aria-label="Clear search and filters" onClick={event => { event.stopPropagation(); onTextChange(''); onTokensChange([]); requestAnimationFrame(focusInput); }}>Clear</button>}
  </form>;
}

